import React, { useState } from "react";
import axios from "axios";

export default function Login({ setUser }) {

  const [nombre, setNombre] = useState("");
  const [email, setEmail] = useState("");
  const [foto, setFoto] = useState(null);

  // 🔥 subir imagen a Cloudinary
  const subirImagen = async () => {
    const formData = new FormData();
    formData.append("file", foto);
    formData.append("upload_preset", "naju_upload");

    const res = await fetch(
      "https://api.cloudinary.com/v1_1/dokjayfkn/image/upload",
      {
        method: "POST",
        body: formData
      }
    );

    const data = await res.json();
    return data.secure_url;
  };

  // 🔥 REGISTRO
  const register = async () => {
    try {
      const imageUrl = await subirImagen();

      const res = await axios.post("http://192.168.100.43:5000/api/auth/register", {
        nombre,
        email,
        password: "1234",
        foto: imageUrl
      });

      alert("Usuario creado");

    } catch (error) {
      console.error(error);
    }
  };

  // 🔥 LOGIN
  const login = async () => {
    try {
      const res = await axios.post("http://192.168.100.43:5000/api/auth/login", {
        email
      });

      setUser(res.data);

    } catch (error) {
      console.error(error);
    }
  };

  return (
    <div style={{ display: "flex", justifyContent: "center", marginTop: 100 }}>
      <div>

        <h2>NA-JU</h2>

        <input 
          placeholder="Nombre"
          onChange={(e) => setNombre(e.target.value)}
        />

        <input 
          placeholder="Email"
          onChange={(e) => setEmail(e.target.value)}
        />

        {/* 🔥 INPUT FOTO */}
        <input 
          type="file"
          onChange={(e) => setFoto(e.target.files[0])}
        />

        <button onClick={register}>Registrarse</button>
        <button onClick={login}>Entrar</button>

      </div>
    </div>
  );
}
